// ANALYZE FOLDERS
// Extracts unique directory paths from the file list and checks if they exist in Notion

// 1. Get Local File Paths
let filePaths = [];
try {
    const binaryData = $items("Read File List")[0].binary.data;
    const b64 = binaryData.data || binaryData;
    const rawOutput = Buffer.from(b64, 'base64').toString('utf8');
    filePaths = rawOutput.split('\n').map(l => l.trim()).filter(l => l.length > 0);
} catch (e) { return []; }

// 2. Get Existing Notion Pages (Map RelativeID -> PageID)
const notionMap = new Map();
$items("Get Notion Pages (Initial)").forEach(item => {
    const rid = item.json.properties.RelativeID?.rich_text?.[0]?.plain_text;
    if (rid) notionMap.set(rid, item.json.id);
});

// 3. Identify Missing Folders
const foldersToCreate = new Set();
const WATCH_DIR = '/data';

filePaths.forEach(fullPath => {
    // Normalize path
    let relPath = fullPath;
    if (relPath.startsWith(WATCH_DIR)) relPath = relPath.slice(WATCH_DIR.length);
    if (relPath.startsWith('/')) relPath = relPath.slice(1);

    // Get directory part (e.g. 'A/B' from 'A/B/file.txt')
    const parts = relPath.split('/');
    parts.pop(); // Remove filename

    // Generate all parent paths (A, A/B)
    let currentPath = '';
    parts.forEach(part => {
        currentPath = currentPath ? `${currentPath}/${part}` : part;
        if (!notionMap.has(currentPath)) {
            foldersToCreate.add(currentPath);
        }
    });
});

// Output objects for creation
return Array.from(foldersToCreate).map(folderPath => ({
    json: {
        name: folderPath.split('/').pop(),
        relativePath: folderPath,
        type: 'Folder'
    }
}));

// ANALYZE FILES & LINK PARENTS

// 1. Get Local Files again
let localFiles = [];
try {
    const binaryData = $items("Read File List")[0].binary.data;
    const b64 = binaryData.data || binaryData;
    const rawOutput = Buffer.from(b64, 'base64').toString('utf8');
    localFiles = rawOutput.split('\n').map(l => l.trim()).filter(l => l.length > 0);
} catch (e) {}

// 2. Get ALL Notion Pages (including new folders)
const notionMap = new Map();
$items("Get Notion Pages (Refresh)").forEach(item => {
    const rid = item.json.properties.RelativeID?.rich_text?.[0]?.plain_text;
    if (rid) notionMap.set(rid, item.json.id);
});

// 3. Prepare File Actions
const results = [];
const WATCH_DIR = '/data';

localFiles.forEach(fullPath => {
    let relPath = fullPath;
    if (relPath.startsWith(WATCH_DIR)) relPath = relPath.slice(WATCH_DIR.length);
    if (relPath.startsWith('/')) relPath = relPath.slice(1);

    const filename = relPath.split('/').pop();
    const parentPath = relPath.split('/').slice(0, -1).join('/');

    const parentId = notionMap.get(parentPath) || null;
    const pageId = notionMap.get(relPath);
    const action = pageId ? 'update' : 'create';

    results.push({
        json: {
            action,
            filename,
            relativePath: relPath,
            pageId,
            parentId,
            magicLink: 'file://' + fullPath
        }
    });
});

return results;
